216: const revealButton=document.querySelector('#revealRole');if(revealButton)revealButton.onclick=()=>{state.revealed=true;render()};if(state.revealed)document.querySelector('#nextRole').onclick=()=>{state.revealed=false;if(last){if(state.settings.typedClues){state.phase='clues';state.clueIndex=0}else{state.startingPlayer=getStartingPlayer();state.verbalStarted=false;state.phase='startingPlayer'}}else state.roleIndex++;render()}
222: function renderStartingPlayer(){app.innerHTML=`<div class="phase-wrap"><div class="phase-head"><div class="eyebrow">ROUND ${state.round} · GAME START</div><span class="round-tag">VERBAL CLUES</span></div><section class="panel phase-card starting-player-card"><div class="eyebrow">WHO'S STARTING?</div><h1 class="starting-player-name">${esc(state.startingPlayer)}</h1><p class="phase-description">You’re the first to give a clue!</p><div class="verbal-instruction">Start the discussion by saying your clue out loud. <strong>No typing required.</strong></div><p class="verbal-status">The group can discuss the secret word and give clues verbally.</p><div class="action-row start-discussion-row"><button id="startVerbalGame" class="primary-btn">START VERBAL DISCUSSION &nbsp;→</button></div></section><div class="setup-footnote">KEEP THE WORD SECRET · EVERYONE GETS ONE VOTE</div></div>`;document.querySelector('#startVerbalGame').onclick=()=>{state.verbalStarted=true;state.phase='verbalDiscussion';if(state.settings.timer)state.seconds=state.settings.timer;render();if(state.settings.timer)startTimer()}}
223: function renderVerbalDiscussion(){app.innerHTML=`<div class="phase-wrap"><div class="phase-head"><div class="eyebrow">ROUND ${state.round} · DISCUSSION</div><span class="round-tag">${state.settings.timer?'DISCUSSION TIMER':'GET TALKING'}</span></div><section class="panel phase-card starting-player-card"><div class="eyebrow">DISCUSSION HAS BEGUN</div><h1 class="starting-player-name">${esc(state.startingPlayer)} <em>starts.</em></h1><p class="phase-description">Give clues out loud, compare ideas, and decide who might be bluffing. No typing required.</p>${state.settings.timer?`<div class="timer" id="timerValue">${clock(state.seconds)}</div>`:''}<div class="action-row"><button id="continueToVote" class="primary-btn">CONTINUE TO VOTING &nbsp;→</button></div></section><div class="setup-footnote">EVERYONE HAS ONE VOTE · YOU CAN’T VOTE FOR YOURSELF</div></div>`;document.querySelector('#continueToVote').onclick=startVoting}
224: function renderClues(){const roles=activeRoles(),p=roles[state.clueIndex];const done=state.clueIndex>=roles.length;app.innerHTML=`<div class="phase-wrap"><div class="phase-head"><div class="eyebrow">ROUND ${state.round} <span>·</span> CLUE ROUND</div><span class="round-tag">${Math.min(state.clueIndex+1,roles.length)} OF ${roles.length}</span></div><section class="panel clue-card"><div class="clue-top"><h2 class="settings-title">One clue. Keep it clever.</h2><span class="pill-info">NO SAYING THE WORD</span></div>${done?`<div class="center"><p class="phase-description">All clues are in. Talk it out, then cast your votes.</p><div class="clue-feed">${state.clues.map(c=>`<div class="clue-item"><span>${esc(c.name)}</span><strong>${esc(c.clue)}</strong></div>`).join('')}</div><button id="beginDiscussion" class="primary-btn" style="max-width:320px">${state.settings.timer?'START DISCUSSION TIMER':'GO TO VOTING'} &nbsp;→</button></div>`:`<div class="current-turn"><span class="avatar">${esc(p.name.charAt(0).toUpperCase())}</span><div><strong>${esc(p.name)}’s turn</strong><small>Pass the phone privately</small></div></div><div class="clue-entry"><input id="clueInput" class="text-input" maxlength="35" autocomplete="off" placeholder="Type a one-word clue…"><button id="submitClue" class="add-btn">Give clue →</button></div><div class="clue-feed">${state.clues.map(c=>`<div class="clue-item"><span>${esc(c.name)}</span><strong>${esc(c.clue)}</strong></div>`).join('')}</div>`}</section><div class="setup-footnote">HINTS, NOT DEFINITIONS. GIVE THEM SOMETHING TO DISCUSS.</div></div>`;
225: if(done){document.querySelector('#beginDiscussion').onclick=()=>{if(state.settings.timer){state.phase='discussion';state.seconds=state.settings.timer;render();startTimer()}else startVoting()}}else{const input=document.querySelector('#clueInput');document.querySelector('#submitClue').onclick=submitClue;input.onkeydown=e=>{if(e.key==='Enter')submitClue()};input.focus()}}
226:function submitClue(){const input=document.querySelector('#clueInput'),clue=input.value.trim();if(!clue){toast('Add a clue before passing the phone.');return}if(clue.toLowerCase().includes(state.word.toLowerCase())){toast('Oops — don’t give the word away!');return}state.clues.push({name:activeRoles()[state.clueIndex].name,clue});state.clueIndex++;render()}
229:function renderDiscussion(){app.innerHTML=`<div class="phase-wrap"><div class="phase-head"><div class="eyebrow">ROUND ${state.round} <span>·</span> DISCUSSION</div><span class="round-tag">GET TALKING</span></div><section class="panel phase-card discussion-card"><div class="eyebrow">TIME LEFT</div><div class="timer" id="timerValue">${clock(state.seconds)}</div><p class="phase-description">Compare the clues. Who sounds like they’re bluffing? Make your case, but don’t give the word away.</p><div class="clue-feed">${state.clues.map(c=>`<div class="clue-item"><span>${esc(c.name)}</span><strong>${esc(c.clue)}</strong></div>`).join('')}</div><div class="action-row"><button id="endDiscussion" class="primary-btn" style="max-width:300px">WE’RE READY TO VOTE &nbsp;→</button></div></section><div class="setup-footnote">EVERYONE HAS ONE VOTE. YOU CAN’T VOTE FOR YOURSELF.</div></div>`;document.querySelector('#endDiscussion').onclick=startVoting}
233:function renderRoundResult(){const r=state.result;const voteHtml=r.activePlayers.map(name=>`<div class="result-player"><span>${esc(name)}${r.leaders.includes(name)?' <b>· TOP VOTE</b>':''}</span><strong>${r.counts[name]} vote${r.counts[name]===1?'':'s'}</strong></div>`).join('');const eliminated=r.eliminated?`<p class="phase-description"><strong>${esc(r.eliminated)}</strong> was eliminated.</p>`:'<p class="phase-description">Skip Vote or a tie won this round. Nobody was eliminated.</p>';app.innerHTML=`<div class="phase-wrap"><div class="phase-head"><div class="eyebrow">ROUND ${state.round} · THE REVEAL</div><span class="round-tag">ROUND OVER</span></div><section class="panel phase-card"><div class="step-count">VOTING RESULTS</div><h1>${r.eliminated?`${esc(r.eliminated)} is out.`:'No elimination.'}</h1>${eliminated}<div class="result-banner"><strong>Imposters still active: ${activePlayers().filter(name=>r.imposters.includes(name)).length}</strong></div><div class="result-grid">${voteHtml}<div class="result-player"><span>Skip Vote</span><strong>${r.counts['Skip Vote']} vote${r.counts['Skip Vote']===1?'':'s'}</strong></div></div><div class="action-row" style="margin-top:22px"><button id="continueRound" class="primary-btn" style="max-width:320px">CONTINUE TO ROUND ${state.round+1} &nbsp;→</button></div></section></div>`;document.querySelector('#continueRound').onclick=()=>{state.round++;state.votes={};state.voteIndex=0;state.selectedVote=null;state.clues=[];state.clueIndex=0;state.startingPlayer='';state.verbalStarted=false;state.phase=state.settings.typedClues?'clues':'startingPlayer';if(!state.settings.typedClues)state.startingPlayer=getStartingPlayer();render()}}
234:function renderGuess(){const imposters=state.result.caught;app.innerHTML=`<div class="phase-wrap"><div class="phase-head"><div class="eyebrow">ONE LAST CHANCE</div><span class="round-tag">IMPOSTER GUESS</span></div><section class="panel phase-card"><div class="step-count">${imposters.map(n=>esc(n.toUpperCase())).join(' & ')}</div><h1>You’ve been found.<br><em>But do you know?</em></h1><p class="phase-description">The room got you. Guess the secret word correctly and steal the win for the imposter team.</p><form id="guessForm" class="clue-entry" style="max-width:400px;margin:0 auto"><input id="guessInput" class="text-input" maxlength="50" autocomplete="off" placeholder="Your final guess…"><button class="add-btn" type="submit">GUESS</button></form></section><div class="setup-footnote">ONE GUESS FOR THE IMPOSTER TEAM. TALK IT OVER.</div></div>`;document.querySelector('#guessForm').onsubmit=e=>{e.preventDefault();const guess=document.querySelector('#guessInput').value.trim();if(!guess){toast('Enter your guess first.');return}finishGame(guess.toLowerCase()===state.word.toLowerCase()?'imposters':'players',guess)}}
235:function finishGame(winner,guess=''){clearInterval(state.interval);if(!state.matchId||state.completedMatchId===state.matchId)return;state.completedMatchId=state.matchId;const party=state.parties.find(p=>p.id===state.activePartyId);if(!party)return;const imposters=[...state.result.imposters];state.players.forEach(name=>{const isImposter=imposters.includes(name),won=(winner==='imposters')===isImposter,reward=won?(isImposter?2:1):0;state.scores[name]=(state.scores[name]||0)+reward;const stat=party.stats[name]||{played:0,wins:0,playerWins:0,imposterRounds:0,imposterWins:0,points:0};stat.played++;if(isImposter)stat.imposterRounds++;if(won){stat.wins++;if(isImposter)stat.imposterWins++;else stat.playerWins++}stat.points+=reward;party.stats[name]=stat});state.result.winner=winner;state.result.guess=guess;party.history.unshift({id:state.matchId,date:new Date().toISOString(),word:state.word,winner,players:[...state.players],imposters,guess,clues:state.clues.map(c=>({...c})),votes:{...state.votes}});state.phase='result';save();render()}

