156: function generateHint(word,category){
157:  const rules=HINT_RULES[category];if(!rules)return '';
158:  const key=word.toLowerCase();
159:  const group=rules.groups.find(rule=>rule.words.split('|').includes(key));
160:  const choices=group?group.hints:rules.fallback;
161:  const index=[...key].reduce((sum,char)=>sum+char.charCodeAt(0),0)%choices.length;
162:  const hint=choices[index];
163:  const hintWords=hint.toLowerCase().split(/[^a-z0-9]+/).filter(Boolean),secretWords=key.split(/[^a-z0-9]+/).filter(Boolean);
164:  const revealsWord=secretWords.length&&hintWords.some((_,i)=>secretWords.every((part,j)=>hintWords[i+j]===part));
165:  return revealsWord?rules.fallback[(index+1)%rules.fallback.length]:hint;
166: }
