237:function renderStats(){const party=state.parties.find(p=>p.id===state.activePartyId);if(!party){state.phase='setup';renderSetup();return}const names=[...new Set([...party.players,...Object.keys(party.stats)])].sort((a,b)=>(party.stats[b]?.points||party.scores[b]||0)-(party.stats[a]?.points||party.scores[a]||0));const selected=state.selectedStatPlayer,stat=selected?party.stats[selected]||{played:0,wins:0,playerWins:0,imposterRounds:0,imposterWins:0,points:party.scores[selected]||0}:null;const history=party.history||[];app.innerHTML=`<div class="phase-wrap stats-wrap"><div class="phase-head"><div><div class="eyebrow">PARTY RECORD</div><h1>${esc(party.name)} <em>stats.</em></h1></div><span class="round-tag">${history.length} MATCH${history.length===1?'':'ES'}</span></div><section class="panel stats-panel"><div class="stats-toolbar"><div><h2 class="settings-title">${selected?`${esc(selected)}’s stats`:'Party leaderboard'}</h2><p class="phase-description">Completed matches only · stored on this device</p></div><button id="backStats" class="secondary-btn">BACK TO SETUP</button></div>${selected?`<div class="stats-metrics"><div><strong>${stat.played}</strong><span>GAMES PLAYED</span></div><div><strong>${stat.wins}</strong><span>TEAM WINS</span></div><div><strong>${stat.playerWins}</strong><span>ROOM WINS</span></div><div><strong>${stat.imposterRounds}</strong><span>IMPOSTER ROUNDS</span></div><div><strong>${stat.imposterWins}</strong><span>IMPOSTER WINS</span></div><div><strong>${stat.points}</strong><span>POINTS</span></div></div><button class="mini-link" id="clearPlayer">← ALL PLAYERS</button>`:`<div class="party-summary"><div><strong>${history.length}</strong><span>COMPLETED MATCHES</span></div><div><strong>${history.filter(m=>m.winner==='players').length}</strong><span>ROOM WINS</span></div><div><strong>${history.filter(m=>m.winner==='imposters').length}</strong><span>IMPOSTER WINS</span></div></div><div class="stats-list">${names.length?names.map((name,i)=>{const s=party.stats[name]||{played:0,wins:0,points:party.scores[name]||0};return`<button class="stats-row" data-stat-player="${esc(name)}"><span class="stats-rank">${i+1}</span><strong>${esc(name)}</strong><span>${s.played} games · ${s.wins} wins</span><b>${s.points} pts</b></button>`}).join(''):'<p class="empty-note">Play a completed match to start your party record.</p>'}</div>`}<div class="history-heading"><h3>MATCH HISTORY</h3><span>${history.length} COMPLETED</span></div><div class="history-list">${history.length?history.slice(0,30).map(m=>`<div class="history-row"><div><strong>${esc(m.word||'—')}</strong><small>${new Date(m.date).toLocaleDateString()} · ${m.players.length} players</small></div><span class="history-winner ${m.winner==='imposters'?'imposter':''}">${m.winner==='imposters'?'IMPOSTER WIN':'ROOM WIN'}</span><small>${m.imposters.map(esc).join(', ')}</small></div>`).join(''):'<p class="empty-note">No completed matches yet.</p>'}</div><div class="stats-footer"><button id="resetStats" class="text-btn danger-text">Reset party stats & history</button></div></section></div>`;document.querySelector('#backStats').onclick=()=>{state.phase='setup';state.selectedStatPlayer=null;render()};document.querySelectorAll('[data-stat-player]').forEach(b=>b.onclick=()=>{state.selectedStatPlayer=b.dataset.statPlayer;render()});document.querySelector('#clearPlayer')?.addEventListener('click',()=>{state.selectedStatPlayer=null;render()});document.querySelector('#resetStats').onclick=()=>{if(!window.confirm(`Reset all scores, stats, and match history for “${party.name}”? This cannot be undone.`))return;party.scores={};party.stats={};party.history=[];state.scores=party.scores;state.selectedStatPlayer=null;save();render();toast('Party stats and history reset.')}}

