157: function generateHint(word,category){
158:  const rules=HINT_RULES[category];if(!rules)return '';
159:  const key=word.toLowerCase();
160:  const group=rules.groups.find(rule=>rule.words.split('|').includes(key));
161:  const choices=group?group.hints:rules.fallback;
162:  const index=[...key].reduce((sum,char)=>sum+char.charCodeAt(0),0)%choices.length;
163:  const hint=choices[index];
164:  const hintWords=hint.toLowerCase().split(/[^a-z0-9]+/).filter(Boolean),secretWords=key.split(/[^a-z0-9]+/).filter(Boolean);
165:  const revealsWord=secretWords.length&&hintWords.some((_,i)=>secretWords.every((part,j)=>hintWords[i+j]===part));
166:  return revealsWord?rules.fallback[(index+1)%rules.fallback.length]:hint;
167: }
