const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright-core');
const assert = require('node:assert/strict');
(async()=>{
  const browser=await chromium.launch({executablePath:'/usr/bin/chromium',headless:true,args:['--no-sandbox']});
  const page=await browser.newPage();
  const errors=[];page.on('pageerror',e=>errors.push(e.message));
  await page.addInitScript(()=>{
    localStorage.setItem('imposter.players',JSON.stringify(['Alex','Sam','Jordan','Taylor']));
    localStorage.setItem('imposter.scores',JSON.stringify({}));
    localStorage.setItem('imposter.settings',JSON.stringify({imposters:1,timer:0,guess:true,categories:['Random Mix'],hints:false,typedClues:true}));
    localStorage.removeItem('imposter.parties');localStorage.removeItem('imposter.activeParty');localStorage.removeItem('imposter.startingPlayer');
  });
  await page.goto('http://127.0.0.1:8765');
  assert.equal(await page.evaluate(()=>JSON.parse(localStorage.getItem('imposter.settings')).typedClues),undefined,'legacy typed mode should be removed from saved settings');
  assert.equal(await page.locator('#app input').count(),1,'setup should have only player-name input and no typed clue controls');
  await page.locator('#startGame').click();
  while(await page.locator('#revealRole').count()){
    await page.locator('#revealRole').click();
    await page.locator('#nextRole').click();
  }
  assert.equal(await page.evaluate(()=>state.phase),'startingPlayer');
  assert.match(await page.locator('#app').innerText(),/VERBAL CLUES|No typing required/i);
  assert.equal(await page.locator('#app input').count(),0,'starting-player phase must not contain a typed clue input');
  const imposter=(await page.evaluate(()=>state.roles.filter(r=>r.imposter).map(r=>r.name)))[0];
  const firstStarter=await page.evaluate(()=>state.startingPlayer);
  await page.locator('#startVerbalGame').click();
  assert.equal(await page.evaluate(()=>state.phase),'verbalDiscussion');
  assert.equal(await page.locator('#timerValue').count(),0,'untimed discussion should omit timer');
  assert.equal(await page.locator('#app input').count(),0,'verbal discussion has no text inputs');
  await page.locator('#continueToVote').click();
  const innocent=(await page.evaluate(()=>state.players.find(n=>!state.roles.find(r=>r.name===n).imposter)));
  while(await page.evaluate(()=>state.phase)==='vote'){
    const voter=await page.evaluate(()=>state.players.filter(n=>!state.eliminated.includes(n))[state.voteIndex]);
    const active=await page.evaluate(()=>state.players.filter(n=>!state.eliminated.includes(n)));
    const target=voter===innocent?'skip':String(active.indexOf(innocent));
    await page.locator(`[data-vote="${target}"]`).click();
    await page.locator('#castVote').click();
  }
  assert.equal(await page.evaluate(()=>state.phase),'roundResult');
  assert.equal(await page.evaluate(()=>state.result.eliminated),innocent,'vote should eliminate the selected innocent player');
  await page.locator('#continueRound').click();
  assert.equal(await page.evaluate(()=>state.phase),'startingPlayer');
  const secondStarter=await page.evaluate(()=>state.startingPlayer);
  assert.notEqual(secondStarter,firstStarter,'starting player should rotate between rounds');
  await page.evaluate(()=>{state.settings.timer=30});
  await page.locator('#startVerbalGame').click();
  assert.equal(await page.evaluate(()=>state.phase),'verbalDiscussion');
  assert.equal(await page.locator('#timerValue').count(),1,'timed discussion should show timer');
  const timeBefore=await page.locator('#timerValue').innerText();
  await page.waitForTimeout(1200);
  const timeAfter=await page.locator('#timerValue').innerText();
  assert.notEqual(timeAfter,timeBefore,'discussion timer should count down');
  await page.locator('#continueToVote').click();
  while(await page.evaluate(()=>state.phase)==='vote'){
    const voter=await page.evaluate(()=>state.players.filter(n=>!state.eliminated.includes(n))[state.voteIndex]);
    const active=await page.evaluate(()=>state.players.filter(n=>!state.eliminated.includes(n)));
    const target=voter===imposter?'skip':String(active.indexOf(imposter));
    await page.locator(`[data-vote="${target}"]`).click();
    await page.locator('#castVote').click();
  }
  assert.equal(await page.evaluate(()=>state.phase),'guess','catching the imposter should allow final guess');
  assert.equal(await page.locator('#guessInput').count(),1);
  const word=await page.evaluate(()=>state.word);
  await page.locator('#guessInput').fill(word);
  await page.locator('#guessForm button[type="submit"]').click();
  assert.equal(await page.evaluate(()=>state.phase),'result');
  assert.equal(await page.evaluate(()=>state.result.winner),'imposters','correct final guess should steal the win');
  assert.deepEqual(errors,[],'browser should not report uncaught errors');
  console.log(JSON.stringify({ok:true,firstStarter,secondStarter,eliminatedInRound1:innocent,imposter,finalGuessCorrect:true,legacyTypedSettingRemoved:true,uncaughtErrors:errors},null,2));
  await browser.close();
})().catch(e=>{console.error(e);process.exit(1)});
